import React, { useState, useEffect } from 'react';
import { onAuthStateChanged, signOut } from 'firebase/auth';
import { auth, dbService } from './services/firebase';
import { ViewState, UserProfile, Order, Product, Customer, Expense, Quote } from './types';
import { Timestamp } from 'firebase/firestore';
import { 
  LayoutDashboard, Users, LogOut, Zap, Building2, Gift, BrainCircuit, Settings, Grid3X3, 
  ShoppingCart, Lock, MessageCircle, FileText, Calendar
} from 'lucide-react';

import LoginView from './views/LoginView';
import MasterDashboard from './views/MasterDashboard';
import OfficeManagement from './views/OfficeManagement';
import NexusHub from './views/NexusHub';
import ProductsView from './views/ProductsView';
import CustomersView from './views/CustomersView';
import OrdersView from './views/OrdersView';
import ExpensesView from './views/ExpensesView';
import AIInsightsView from './views/AIInsightsView';
import SettingsView from './views/SettingsView';
import ReferralView from './views/ReferralView';
import QuotesView from './views/QuotesView';
import CalendarView from './views/CalendarView';
import GenericModuleView from './views/GenericModuleView';

const App: React.FC = () => {
  const [user, setUser] = useState<any>(null);
  const [profile, setProfile] = useState<UserProfile | null>(null);
  const [view, setView] = useState<ViewState>('MASTER_DASHBOARD');
  const [loading, setLoading] = useState(true);

  const [orders, setOrders] = useState<Order[]>([]);
  const [quotes, setQuotes] = useState<Quote[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [expenses, setExpenses] = useState<Expense[]>([]);

  useEffect(() => {
    return onAuthStateChanged(auth, async (u) => {
      if (u) {
        let p = await dbService.getUserProfile(u.uid);
        if (!p) p = await dbService.initProfile(u.uid, u.email || '');

        const isMaster = u.email === "giufarlosdias@hotmail.com";
        if (isMaster) {
           const infiniteDate = new Date(2099, 11, 31);
           await dbService.update('users', u.uid, { 
             role: 'super-admin',
             subscriptionStatus: 'PAID',
             status: 'active',
             subscriptionExpiresAt: Timestamp.fromDate(infiniteDate)
           });
           p.role = 'super-admin';
           p.subscriptionStatus = 'PAID';
           p.status = 'active';
        }

        if (p.status === 'blocked') { alert("Terminal Bloqueado."); await signOut(auth); return; }

        setProfile(p as UserProfile);
        setUser(u);
        setView(p.role === 'super-admin' ? 'MASTER_DASHBOARD' : 'MY_HUB');

        if (p.role === 'admin' || p.role === 'super-admin') {
          dbService.sync('orders', u.uid, (data) => setOrders(data as Order[]));
          dbService.sync('quotes', u.uid, (data) => setQuotes(data as Quote[]));
          dbService.sync('products', u.uid, (data) => setProducts(data as Product[]));
          dbService.sync('customers', u.uid, (data) => setCustomers(data as Customer[]));
          dbService.sync('expenses', u.uid, (data) => setExpenses(data as Expense[]));
        }
      } else {
        setUser(null); setProfile(null);
      }
      setLoading(false);
    });
  }, []);

  if (loading) return (
    <div className="h-screen w-full flex flex-col items-center justify-center bg-[#05010d]">
      <div className="relative">
        <div className="w-16 h-16 border-2 border-cyan-400/20 rounded-full"></div>
        <div className="absolute top-0 left-0 w-16 h-16 border-t-2 border-cyan-400 rounded-full animate-spin"></div>
        <Zap className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 text-cyan-400 animate-pulse" size={24}/>
      </div>
      <p className="mt-8 font-terminal text-[10px] text-cyan-400 uppercase tracking-[0.5em] animate-pulse">Sincronizando Nexus OS</p>
    </div>
  );

  if (!user) return <LoginView />;

  const isSuper = profile?.role === 'super-admin';
  const salesCount = orders.filter(o => o.status === 'PAID').length;
  const needsPayment = !isSuper && salesCount >= 3 && profile?.subscriptionStatus !== 'PAID';

  const NavContent = () => (
    <div className="flex flex-row lg:flex-col items-center justify-around lg:justify-start w-full h-full lg:h-auto gap-2 lg:gap-4 px-4 lg:px-0">
      {isSuper ? (
        <>
          <button onClick={()=>setView('MASTER_DASHBOARD')} title="Painel Global" className={`nav-btn p-3 lg:p-5 flex-1 lg:w-full ${view==='MASTER_DASHBOARD'?'active':''}`}><LayoutDashboard size={22}/></button>
          <button onClick={()=>setView('OFFICE_MANAGEMENT')} title="Gestão Escritórios" className={`nav-btn p-3 lg:p-5 flex-1 lg:w-full ${view==='OFFICE_MANAGEMENT'?'active':''}`}><Building2 size={22}/></button>
          <button onClick={()=>setView('MY_HUB')} title="Visão de Operador" className={`nav-btn p-3 lg:p-5 flex-1 lg:w-full ${view==='MY_HUB'?'active':''}`}><Grid3X3 size={22}/></button>
        </>
      ) : (
        <>
          <button onClick={()=>setView('MY_HUB')} className={`nav-btn p-3 lg:p-5 flex-1 lg:w-full ${view==='MY_HUB'?'active':''}`}><Grid3X3 size={22}/></button>
          <button onClick={()=>setView('ORDERS')} className={`nav-btn p-3 lg:p-5 flex-1 lg:w-full ${view==='ORDERS'?'active':''}`}><ShoppingCart size={22}/></button>
          <button onClick={()=>setView('QUOTES')} className={`nav-btn p-3 lg:p-5 flex-1 lg:w-full ${view==='QUOTES'?'active':''}`}><FileText size={22}/></button>
          <button onClick={()=>setView('CALENDAR')} className={`nav-btn p-3 lg:p-5 flex-1 lg:w-full ${view==='CALENDAR'?'active':''}`}><Calendar size={22}/></button>
        </>
      )}
      <div className="hidden lg:block w-8 h-px bg-white/10 mx-auto my-4"></div>
      <button onClick={() => setView('SETTINGS')} className={`nav-btn p-3 lg:p-5 flex-1 lg:w-full ${view === 'SETTINGS' ? 'active' : ''}`}><Settings size={22}/></button>
      <button onClick={() => signOut(auth)} className="nav-btn p-3 lg:p-5 flex-1 lg:w-full text-rose-500 hover:bg-rose-500/10"><LogOut size={22}/></button>
    </div>
  );

  const renderView = () => {
    if (needsPayment && view !== 'SETTINGS') {
      return (
        <div className="h-full flex flex-col items-center justify-center space-y-8 p-6 text-center animate-fade-in">
          <div className="w-20 h-20 bg-rose-500 rounded-3xl flex items-center justify-center shadow-lg box-glow-rose"><Lock size={32} className="text-white"/></div>
          <h2 className="text-3xl font-black text-white uppercase italic tracking-tighter">Terminal em Espera</h2>
          <p className="text-slate-500 text-[11px] uppercase font-black tracking-widest max-w-xs">Identificamos atividade pendente de regularização. Contate o administrador.</p>
          <button onClick={() => signOut(auth)} className="text-rose-500 font-black uppercase text-[10px] tracking-[0.5em] mt-10 hover:text-white transition-colors">Encerrar Sessão</button>
        </div>
      );
    }

    switch(view) {
      case 'MASTER_DASHBOARD': return <MasterDashboard />;
      case 'OFFICE_MANAGEMENT': return <OfficeManagement />;
      case 'MY_HUB': return <NexusHub setView={setView} />;
      case 'ORDERS': return <OrdersView orders={orders} products={products} customers={customers} userId={user.uid} profile={profile!} />;
      case 'QUOTES': return <QuotesView quotes={quotes} products={products} customers={customers} userId={user.uid} profile={profile!} />;
      case 'PRODUCTS': return <ProductsView userId={user.uid} />;
      case 'CUSTOMERS': return <CustomersView customers={customers} orders={orders} userId={user.uid} />;
      case 'EXPENSES': return <ExpensesView expenses={expenses} userId={user.uid} profile={profile!} />;
      case 'REFERRALS': return <ReferralView profile={profile!} />;
      case 'AI_INSIGHTS': return <AIInsightsView orders={orders} products={products} />;
      case 'SETTINGS': return <SettingsView profile={profile!} />;
      case 'CALENDAR': return <CalendarView profile={profile!} userId={user.uid} />;
      default: return <GenericModuleView onBack={()=>setView('MY_HUB')} title="Módulo Nexus" icon={<Zap/>}/>;
    }
  };

  return (
    <div className="flex flex-col lg:flex-row h-screen bg-[#05010d] overflow-hidden">
      <div className="absolute inset-0 grid-bg opacity-30 pointer-events-none"></div>

      <aside className="hidden lg:flex w-72 border-r border-white/5 bg-[#0c0628]/90 backdrop-blur-3xl flex-col p-8 z-20">
        <div className="flex items-center gap-4 mb-16 px-2">
          <div className="w-10 h-10 bg-cyan-400 rounded-xl flex items-center justify-center shadow-lg box-glow-cyan"><Zap size={20} className="text-black fill-current"/></div>
          <div><span className="font-terminal font-black text-lg block text-glow-cyan">RADIANT</span><span className="text-[8px] font-black text-slate-500 tracking-[0.4em] uppercase opacity-60">CORE 3.0 ELITE</span></div>
        </div>
        <NavContent />
      </aside>

      <main className="flex-1 overflow-y-auto p-4 md:p-12 relative z-10 custom-scrollbar pb-24 lg:pb-12">
        {renderView()}
      </main>

      <nav className="lg:hidden fixed bottom-0 left-0 right-0 h-22 bg-[#0c0628]/95 backdrop-blur-3xl border-t border-white/10 flex items-center z-50 px-2 pb-2">
        <NavContent />
      </nav>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { Calendar as CalendarIcon, Clock, Plus, Bell, Trash2, Zap, MessageCircle, X } from 'lucide-react';
import { dbService } from '../services/firebase';
import { UserProfile } from '../types';

interface CalendarViewProps {
  profile: UserProfile;
  userId: string;
}

const CalendarView: React.FC<CalendarViewProps> = ({ profile, userId }) => {
  const [events, setEvents] = useState<any[]>([]);
  const [reportActive, setReportActive] = useState(true);

  // O estado do último relatório agora vem do perfil sincronizado (Zero LocalStorage)
  const [lastReportSent, setLastReportSent] = useState<string | null>( (profile as any).lastReportDate || null );

  useEffect(() => {
    // Sincronização de eventos (simulada ou via sync real)
    const initialEvents = [
      { id: '1', title: 'Visita Técnica Cliente Silva', time: '09:00', date: new Date().toISOString().split('T')[0] },
      { id: '2', title: 'Reunião de Alinhamento Nexus', time: '14:30', date: new Date().toISOString().split('T')[0] }
    ];

    const today = new Date();
    today.setHours(0,0,0,0);

    const filtered = initialEvents.filter(e => {
      const eDate = new Date(e.date);
      return eDate >= today;
    });

    setEvents(filtered);
  }, []);

  useEffect(() => {
    if (!reportActive) return;

    const checkReport = async () => {
      const now = new Date();
      const todayKey = now.toLocaleDateString();

      if (lastReportSent === todayKey) return;

      const currentHour = now.getHours();
      const currentMin = now.getMinutes();

      // Gatilho Matinal Nexus: 06:30
      if (currentHour > 6 || (currentHour === 6 && currentMin >= 30)) {
        await triggerAutomaticReport();
        setLastReportSent(todayKey);
        // Persiste no Firestore em vez de LocalStorage
        await dbService.update('users', userId, { lastReportDate: todayKey });
      }
    };

    const interval = setInterval(checkReport, 60000);
    checkReport();
    return () => clearInterval(interval);
  }, [reportActive, lastReportSent, events, userId]);

  const triggerAutomaticReport = async () => {
    if (events.length === 0) return;

    let msg = `*📅 NEXUS OS - RELATÓRIO MATINAL (06:30)*\n`;
    msg += `*Terminal:* ${profile.officeName}\n`;
    msg += `*Data:* ${new Date().toLocaleDateString('pt-BR')}\n`;
    msg += `--------------------------\n`;
    events.forEach(e => {
      msg += `⏰ ${e.time} - ${e.title.toUpperCase()}\n`;
    });
    msg += `--------------------------\n`;
    msg += `_Sincronização Cloud Nexus OS_`;

    const phone = profile.phone?.replace(/\D/g, '') || '5511910688022';
    window.open(`https://wa.me/${phone}?text=${encodeURIComponent(msg)}`, '_blank');
  };

  return (
    <div className="space-y-12 animate-fade-in pb-20">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-8">
        <div>
          <h2 className="text-4xl lg:text-5xl font-black text-white italic tracking-tighter text-glow-cyan leading-none uppercase">Agenda Nexus</h2>
          <p className="text-slate-500 font-bold mt-4 text-sm uppercase tracking-widest opacity-70">Monitoramento e limpeza automática de ciclos.</p>
        </div>
        <div className="flex items-center gap-4 bg-white/5 p-4 rounded-[2rem] border border-white/10 box-glow-cyan">
           <div className="text-right">
              <p className="text-[10px] font-black text-cyan-400 uppercase tracking-widest">Relatório Cloud 06:30 AM</p>
              <p className="text-[8px] text-slate-500 uppercase font-black">{reportActive ? 'Protocolo Ativo' : 'Protocolo Suspenso'}</p>
           </div>
           <button 
             onClick={() => setReportActive(!reportActive)}
             className={`w-14 h-8 rounded-full relative transition-all ${reportActive ? 'bg-emerald-500' : 'bg-white/10'}`}
           >
             <div className={`absolute top-1 w-6 h-6 rounded-full bg-white transition-all ${reportActive ? 'right-1' : 'left-1'}`}></div>
           </button>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-10">
        <div className="lg:col-span-2 space-y-6">
           {events.map(event => (
             <div key={event.id} className="nexus-card p-8 flex items-center justify-between group hover:border-cyan-400/30">
               <div className="flex items-center gap-8">
                 <div className="w-16 h-16 rounded-2xl bg-white/5 border border-white/10 flex flex-col items-center justify-center">
                    <p className="text-[10px] font-black text-cyan-400 uppercase">DIA</p>
                    <p className="text-2xl font-black text-white">{event.date.split('-')[2]}</p>
                 </div>
                 <div>
                    <h4 className="text-xl font-black text-white uppercase italic tracking-tight">{event.title}</h4>
                    <div className="flex items-center gap-4 mt-2">
                       <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest flex items-center gap-2"><Clock size={12}/> {event.time}</p>
                    </div>
                 </div>
               </div>
               <button onClick={() => setEvents(events.filter(e => e.id !== event.id))} className="p-4 text-slate-700 hover:text-rose-500 transition-all opacity-0 group-hover:opacity-100">
                  <Trash2 size={24}/>
               </button>
             </div>
           ))}
           {events.length === 0 && (
             <div className="py-20 text-center border-2 border-dashed border-white/5 rounded-[2.5rem]">
                <p className="text-slate-600 font-black uppercase text-[10px] tracking-widest">Nenhum compromisso pendente para hoje.</p>
             </div>
           )}
           <button className="w-full py-8 border-2 border-dashed border-white/5 rounded-[2.5rem] flex items-center justify-center gap-4 text-slate-700 hover:text-cyan-400 hover:border-cyan-400/30 transition-all group font-black uppercase text-xs">
              <Plus size={32} className="group-hover:scale-110 transition-transform"/> AGENDAR NOVO COMPROMISSO
           </button>
        </div>

        <div className="nexus-card p-10 bg-[#0c0628] border-cyan-400/20 h-fit">
           <h3 className="font-terminal text-sm font-black text-cyan-400 uppercase tracking-widest mb-8 flex items-center gap-3"><Bell size={18}/> Status Nexus Cloud</h3>
           <div className="space-y-6">
              <div className="p-6 bg-white/5 rounded-2xl border border-white/5">
                 <p className="text-[9px] font-black text-slate-500 uppercase mb-2">Relatório Hoje</p>
                 <div className="flex items-center gap-3 text-emerald-400">
                    <MessageCircle size={16}/>
                    <span className="text-[10px] font-black uppercase tracking-widest">
                      {lastReportSent === new Date().toLocaleDateString() ? 'SINCRONIZADO OK' : 'AGUARDANDO 06:30'}
                    </span>
                 </div>
              </div>
              <div className="p-6 bg-white/5 rounded-2xl border border-white/5">
                 <p className="text-[9px] font-black text-slate-500 uppercase mb-2">Persistência</p>
                 <p className="text-2xl font-black text-white italic">CLOUD SYNC</p>
                 <p className="text-[8px] text-slate-700 font-bold uppercase mt-1">Nenhum dado local detectado.</p>
              </div>
           </div>
        </div>
      </div>
    </div>
  );
};

export default CalendarView;

import React, { useState, useEffect } from 'react';
import { 
  TrendingUp, Users, DollarSign, Zap, 
  Activity, PieChart, ShieldCheck, AlertCircle
} from 'lucide-react';
import { dbService } from '../services/firebase';

const MasterDashboard: React.FC = () => {
  const [network, setNetwork] = useState({
    totalOffices: 0,
    activeSubscribers: 0,
    mrr: 0,
    payoutL1: 0,
    payoutL2: 0,
    payoutL3: 0
  });

  useEffect(() => {
    return dbService.watchNetwork((users) => {
      const active = users.filter(u => u.subscriptionStatus === 'PAID' && u.role === 'admin');
      const mrr = active.length * 50;
      const l1 = users.filter(u => u.lineage?.l1 && u.subscriptionStatus === 'PAID').length * 1.00;
      const l2 = users.filter(u => u.lineage?.l2 && u.subscriptionStatus === 'PAID').length * 0.50;
      const l3 = users.filter(u => u.lineage?.l3 && u.subscriptionStatus === 'PAID').length * 0.25;

      setNetwork({
        totalOffices: users.filter(u => u.role === 'admin').length,
        activeSubscribers: active.length,
        mrr,
        payoutL1: l1,
        payoutL2: l2,
        payoutL3: l3
      });
    });
  }, []);

  const stats = [
    { label: 'Fluxo Recorrente', value: `R$ ${network.mrr.toFixed(2)}`, icon: <DollarSign />, color: 'text-emerald-400', glow: 'text-glow-cyan' },
    { label: 'Terminais Ativos', value: network.activeSubscribers, icon: <Users />, color: 'text-cyan-400', glow: 'text-glow-cyan' },
    { label: 'Residual Rede', value: `R$ ${(network.payoutL1 + network.payoutL2 + network.payoutL3).toFixed(2)}`, icon: <PieChart />, color: 'text-purple-400', glow: 'text-glow-purple' },
    { label: 'Performance Global', value: `${network.totalOffices > 0 ? ((network.activeSubscribers / network.totalOffices) * 100).toFixed(1) : 0}%`, icon: <TrendingUp />, color: 'text-amber-400', glow: 'text-glow-rose' }
  ];

  return (
    <div className="space-y-16 animate-fade-in">
      <div className="flex flex-col lg:flex-row justify-between lg:items-end gap-10">
        <div>
          <h2 className="text-6xl font-black text-white italic tracking-tighter text-glow-cyan leading-none uppercase">Nexus Master Control</h2>
          <p className="text-slate-500 font-bold text-sm tracking-[0.5em] uppercase mt-8 flex items-center gap-4">
            <ShieldCheck size={20} className="text-cyan-400" /> Monitoramento Global de Terminais Operacionais
          </p>
        </div>
        <div className="nexus-card px-10 py-6 border border-white/5 flex gap-12 bg-white/5">
           <div className="text-right">
             <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-2">Network Global</p>
             <p className="text-3xl font-black text-white italic tracking-tighter">{network.totalOffices}</p>
           </div>
           <div className="w-px h-12 bg-white/5"></div>
           <div className="text-right">
             <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-2">Saúde da Rede</p>
             <p className="text-3xl font-black text-cyan-400 italic tracking-tighter text-glow-cyan">NOMINAL</p>
           </div>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-10">
        {stats.map((s, i) => (
          <div key={i} className="nexus-card p-10 group overflow-hidden relative border-white/5 hover:border-cyan-400/30 transition-all">
            <div className={`absolute -right-6 -top-6 opacity-5 group-hover:scale-150 transition-transform ${s.color}`}>
              {React.cloneElement(s.icon as React.ReactElement<any>, { size: 120 })}
            </div>
            <div className={`w-14 h-14 rounded-2xl bg-white/5 flex items-center justify-center mb-8 ${s.color} border border-white/5`}>
              {React.cloneElement(s.icon as React.ReactElement<any>, { size: 28 })}
            </div>
            <p className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] mb-3">{s.label}</p>
            <p className={`text-4xl font-black text-white tracking-tighter italic ${s.glow}`}>{s.value}</p>
          </div>
        ))}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-12">
        <div className="lg:col-span-2 nexus-card p-12 relative overflow-hidden">
           <div className="absolute top-0 right-0 p-12 opacity-5 pointer-events-none"><Zap size={200} className="text-cyan-400" /></div>
           <div className="flex justify-between items-center mb-14 relative z-10">
              <h3 className="font-terminal text-sm font-black text-glow-cyan uppercase tracking-widest">Distribuição Residual Ativa</h3>
              <Activity className="text-cyan-400/30 animate-pulse" />
           </div>
           <div className="space-y-12 relative z-10">
              {[
                { level: 'L1', title: 'Operação Direta', desc: 'R$ 1,00/mês por terminal', val: network.payoutL1, color: 'cyan' },
                { level: 'L2', title: 'Expansão de Rede', desc: 'R$ 0,50/mês por terminal', val: network.payoutL2, color: 'purple' },
                { level: 'L3', title: 'Incentivo Global', desc: 'R$ 0,25/mês por terminal', val: network.payoutL3, color: 'rose' }
              ].map((row, i) => (
                <div key={i} className="flex items-center justify-between group">
                  <div className="flex items-center gap-8">
                    <div className={`w-16 h-16 rounded-[1.5rem] bg-${row.color}-400/10 flex items-center justify-center text-${row.color}-400 font-black border border-${row.color}-400/20 box-glow-${row.color}`}>
                      {row.level}
                    </div>
                    <div>
                      <p className="text-white font-black uppercase text-base tracking-tight">{row.title}</p>
                      <p className="text-[10px] text-slate-600 font-bold uppercase mt-1 tracking-widest">{row.desc}</p>
                    </div>
                  </div>
                  <p className={`text-4xl font-black text-white italic group-hover:text-${row.color}-400 transition-colors text-glow-${row.color}`}>R$ {row.val.toFixed(2)}</p>
                </div>
              ))}
           </div>
        </div>

        <div className="nexus-card p-12 relative overflow-hidden group bg-gradient-to-br from-rose-500/5 to-transparent border-rose-500/10">
           <h3 className="font-terminal text-[10px] font-black text-rose-500 uppercase tracking-[0.4em] mb-12">Diagnóstico de Churn</h3>
           <div className="space-y-8">
              <div className="p-8 bg-black/40 rounded-3xl border border-white/5 group-hover:border-rose-500/30 transition-all">
                <p className="text-[10px] font-black text-slate-600 uppercase mb-3 tracking-widest">Taxa de Evasão</p>
                <p className="text-4xl font-black text-rose-500 italic tracking-tighter text-glow-rose">
                  {network.totalOffices > 0 ? (((network.totalOffices - network.activeSubscribers) / network.totalOffices) * 100).toFixed(1) : 0}%
                </p>
