import { GoogleGenAI } from "@google/genai";
import { Order, Product } from "../types";

export async function getSalesInsights(orders: Order[], products: Product[]) {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  if (orders.length === 0) return "### Matriz de Dados Vazia\nSincronize as primeiras operações para habilitar o processamento preditivo.";

  const prompt = `
    Aja como o NEXUS RADIANT CORE 3.0, uma inteligência artificial de elite especializada em gestão agnóstica de negócios.

    ESTATÍSTICAS ATUAIS:
    - Total de Vendas Processadas: ${orders.length}
    - Valor Bruto em Trânsito: R$ ${orders.reduce((s,o) => s + o.total, 0).toFixed(2)}
    - Itens em Inventário: ${products.length}

    DADOS BRUTOS PARA PROCESSAMENTO:
    Vendas: ${JSON.stringify(orders.slice(0, 20))}
    Produtos: ${JSON.stringify(products)}

    ESTRUTURA DO RELATÓRIO ELITE:
    1. ⚡ **Sincronização de Fluxo**: Analise a frequência e o ticket médio.
    2. 🎯 **Otimização de Estoque**: Identifique o que é "Peso Morto" e o que é "Alta Tensão" (giro rápido).
    3. 🚀 **Protocolo de Expansão**: Sugira uma estratégia agressiva para aumentar o lucro em 15% nos próximos 30 dias.

    Use linguagem futurista, técnica e extremamente profissional. Use Markdown de alta qualidade.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: prompt,
    });
    return response.text;
  } catch (error) {
    console.error("Gemini Failure:", error);
    return "### Erro de Conexão Neural\nFalha ao contatar o núcleo Radiant. Verifique sua chave de API e tente novamente.";
  }
}
